-- Create a temporary table variable to hold the output actions. DECLARE @SummaryOfChanges TABLE(Change VARCHAR(20));
MERGE INTO Sales.SalesReason AS Target USING (VALUES ('Recommendation','Other'), ('Review', 'Marketing'), ('Internet', 'Promotion')) AS Source (NewName, NewReasonType) ON Target.Name = Source.NewName WHEN MATCHED THEN UPDATE SET ReasonType = Source.NewReasonType WHEN NOT MATCHED BY TARGET THEN INSERT (Name, ReasonType) VALUES (NewName, NewReasonType) OUTPUT $action INTO @SummaryOfChanges OPTION (LOOP JOIN);
-- Query the results of the table variable. SELECT Change, COUNT(*) AS CountPerChange FROM @SummaryOfChanges GROUP BY Change;

IF OBJECT_ID( 'tempdb..#CustomerChanges') IS NOT NULL DROP TABLE #CustomerChanges;
CREATE TABLE #CustomerChanges( ChangeType NVARCHAR(10) ,CustomerNum TINYINT NOT NULL ,NewCustomerName VARCHAR(25) NULL ,PrevCustomerName VARCHAR(25) NULL ,NewPlanet VARCHAR(25) NULL ,PrevPlanet VARCHAR(25) NULL ,UserName NVARCHAR(100) NOT NULL ,DateTimeChanged DateTime NOT NULL);
MERGE #Customer_New AS Target USING #Customer_Orig AS Source ON Target.CustomerNum = Source.CustomerNum WHEN MATCHED AND EXISTS (SELECT Source.CustomerName, Source.Planet EXCEPT SELECT Target.CustomerName, Target.Planet) THEN UPDATE SET Target.CustomerName = Source.CustomerName, Target.Planet = Source.Planet WHEN NOT MATCHED BY TARGET THEN INSERT (CustomerNum, CustomerName, Planet) VALUES (Source.CustomerNum, Source.CustomerName, Source.Planet) WHEN NOT MATCHED BY SOURCE THEN DELETE ------------------------------------- OUTPUT $ACTION ChangeType, coalesce (inserted.CustomerNum, deleted.CustomerNum) CustomerNum, inserted.CustomerName NewCustomerName, deleted.CustomerName PrevCustomerName, inserted.Planet NewPlanet, deleted.Planet PrevPlanet, SUSER_SNAME() UserName, Getdate () DateTimeChanged INTO #CustomerChanges ------------------------------------- ;
SELECT * FROM #CustomerChanges;
